// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PlatformListConnectorTypes Every connector_type this process's own Registry knows how to drive, with its capabilities (PLT-20)
	// (GET /admin/v1/platform/connector-types)
	PlatformListConnectorTypes(ctx context.Context, request PlatformListConnectorTypesRequestObject) (PlatformListConnectorTypesResponseObject, error)
	// PlatformListConnectors The tenant's registered connectors (PLT-20)
	// (GET /admin/v1/platform/connectors)
	PlatformListConnectors(ctx context.Context, request PlatformListConnectorsRequestObject) (PlatformListConnectorsResponseObject, error)
	// PlatformCreateConnector Register a new connector (PLT-20) — its secret, if any, is sealed via the PLT-13 Keyring, never returned
	// (POST /admin/v1/platform/connectors)
	PlatformCreateConnector(ctx context.Context, request PlatformCreateConnectorRequestObject) (PlatformCreateConnectorResponseObject, error)
	// PlatformDeleteConnector Remove a connector and its own sealed secret, if any (PLT-20)
	// (DELETE /admin/v1/platform/connectors/{id})
	PlatformDeleteConnector(ctx context.Context, request PlatformDeleteConnectorRequestObject) (PlatformDeleteConnectorResponseObject, error)
	// PlatformGetConnector One connector, never carrying its own decrypted secret (PLT-20)
	// (GET /admin/v1/platform/connectors/{id})
	PlatformGetConnector(ctx context.Context, request PlatformGetConnectorRequestObject) (PlatformGetConnectorResponseObject, error)
	// PlatformUpdateConnector Change a connector's own name/config/secret/capabilities (PLT-20)
	// (PATCH /admin/v1/platform/connectors/{id})
	PlatformUpdateConnector(ctx context.Context, request PlatformUpdateConnectorRequestObject) (PlatformUpdateConnectorResponseObject, error)
	// PlatformTestConnector Test the connection from the admin screen (PLT-20's own acceptance criterion) — updates status/last_tested_at
	// (POST /admin/v1/platform/connectors/{id}/test)
	PlatformTestConnector(ctx context.Context, request PlatformTestConnectorRequestObject) (PlatformTestConnectorResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

